script:
(function () {
  'use strict';
  // Saving for a home: down payment + closing costs on a price that grows while you save.
  //   Price after t months: P(t) = P0 x (1 + g)^(t / 12). Cash needed: C(t) = P(t) x (down% + closing%).
  //   Savings after t months, deposits D at each month end, monthly rate i = return / 12:
  //   S(t) = S0 x (1 + i)^t + D x ((1 + i)^t - 1) / i   (S0 + D x t at 0%).
  //   Monthly saving needed for a purchase in T months: D = (C(T) - S0 (1 + i)^T) / (((1 + i)^T - 1) / i),
  //   or $0 when current savings already grow past C(T).
  //   Earliest purchase at your monthly amount: the first month t (0 to 360) with S(t) >= C(t).
  // Verified in Node (scratchpad b6mtg/hs.test.js): $350,000 price, 3% growth, 3 years: price
  //   $382,454.45 (350,000 x 1.03^3), 13% cash = $49,719.08; $15,000 at 4% grows to $16,909.08 and
  //   the annuity factor is 38.1816, so D = $859.32 (closed form; the S(T) it produces equals C(T) to
  //   the cent); with $800 a month the first month S(t) >= C(t) is month 39 (3 years 3 months), checked by an
  //   independent month-by-month loop;
  //   0% return gives (C - S0) / T; savings above the target give $0; growth faster than savings
  //   gives "not within 30 years"; no NaN/Infinity on blank or bad input.
  var MAX_MONTHS = 360;
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAs) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAs === undefined ? NaN : blankAs;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function price(p0, g, t) { return p0 * Math.pow(1 + g, t / 12); }

  function savings(s0, dep, i, t) {
    if (t <= 0) return s0;
    if (i === 0) return s0 + dep * t;
    var f = Math.pow(1 + i, t);
    return s0 * f + dep * (f - 1) / i;
  }

  function annuity(i, t) { return i === 0 ? t : (Math.pow(1 + i, t) - 1) / i; }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function clearResults() {
    ['hsNeedPay', 'hsCash', 'hsGrowthCost', 'hsEarliest'].forEach(function (id) { setText(id, '–'); setText(id + 'Note', ''); });
    ['hsFuturePrice', 'hsDownAmt', 'hsClosingAmt', 'hsSavedGrows', 'hsDeposits', 'hsInterest'].forEach(function (id) { setText(id, '–'); });
    el('hsChase').hidden = true;
    el('hsTable').innerHTML = '';
  }

  function update() {
    var p0 = read('hsPrice'), down = read('hsDown'), closing = read('hsClosing', 0), growth = read('hsGrowth', 0),
        s0 = read('hsSaved', 0), ret = read('hsReturn', 0), years = read('hsYears'), dep = read('hsMonthly', 0);
    var msg = '';
    if (isNaN(p0) || p0 <= 0 || p0 > 1e9) msg = 'Enter a home price greater than $0.';
    else if (isNaN(down) || down < 0 || down > 100) msg = 'Enter a down payment from 0% to 100%.';
    else if (isNaN(closing) || closing < 0 || closing > 15) msg = 'Enter closing costs from 0% to 15%.';
    else if (down + closing <= 0) msg = 'Enter a down payment or closing costs above 0% so there is something to save for.';
    else if (isNaN(growth) || growth < -10 || growth > 20) msg = 'Enter home price growth from -10% to 20% a year.';
    else if (isNaN(s0) || s0 < 0 || s0 > 1e9) msg = 'Enter savings of $0 or more.';
    else if (isNaN(ret) || ret < 0 || ret > 20) msg = 'Enter a return on savings from 0% to 20%.';
    else if (isNaN(years) || years < 1 || years > 30 || years % 1 !== 0) msg = 'Enter when you want to buy: 1 to 30 whole years.';
    else if (isNaN(dep) || dep < 0 || dep > 1e7) msg = 'Enter a monthly saving amount of $0 or more.';
    var error = el('hsError');
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var g = growth / 100, i = ret / 1200, share = (down + closing) / 100, T = years * 12;
    function need(t) { return price(p0, g, t) * share; }
    var cashT = need(T), grownS0 = savings(s0, 0, i, T);
    var D = Math.max(0, (cashT - grownS0) / annuity(i, T));

    setText('hsNeedPay', money.format(D));
    setText('hsNeedPayNote', D === 0 ? 'What you have saved already grows past the target by then.' : 'Every month for ' + duration(T) + ', on top of the ' + money0.format(s0) + ' you have.');
    setText('hsCash', money.format(cashT));
    setText('hsCashNote', down + '% down plus ' + closing + '% closing costs on a ' + money0.format(price(p0, g, T)) + ' home.');
    var growthCost = cashT - need(0);
    setText('hsGrowthCost', (growthCost < 0 ? '−' : '') + money.format(Math.abs(growthCost)));
    setText('hsGrowthCostNote', 'Compared with the ' + money.format(need(0)) + ' you would need at today’s price.');

    var earliest = -1;
    for (var t = 0; t <= MAX_MONTHS; t++) {
      if (savings(s0, dep, i, t) >= need(t) - 0.005) { earliest = t; break; }
    }
    var chase = el('hsChase');
    if (earliest === 0) { setText('hsEarliest', 'Now'); setText('hsEarliestNote', 'Your savings already cover the cash needed at today’s price.'); }
    else if (earliest > 0) {
      setText('hsEarliest', duration(earliest));
      setText('hsEarliestNote', 'Saving ' + money.format(dep) + ' a month, when the home would cost about ' + money0.format(price(p0, g, earliest)) + '. That is ' + (earliest <= T ? duration(T - earliest) + ' before' : duration(earliest - T) + ' after') + ' your target date.');
    } else {
      setText('hsEarliest', 'Not within 30 years');
      setText('hsEarliestNote', dep === 0 ? 'Enter how much you can save each month to see when you could buy.' : 'At ' + money.format(dep) + ' a month your savings do not catch up with the ' + (g > 0 ? 'rising ' : '') + 'cash needed.');
    }
    chase.hidden = earliest >= 0 || need(12) <= need(0);
    if (earliest < 0) setText('hsChaseText', 'The cash needed grows by about ' + money.format(need(12) - need(0)) + ' in the first year alone. Save more each month, aim for a lower price or smaller down payment, or look at loans that need less cash.');

    var futurePrice = price(p0, g, T);
    setText('hsFuturePrice', money.format(futurePrice));
    setText('hsDownAmt', money.format(futurePrice * down / 100));
    setText('hsClosingAmt', money.format(futurePrice * closing / 100));
    setText('hsSavedGrows', money.format(grownS0));
    var final = savings(s0, D, i, T);
    setText('hsDeposits', money.format(D * T));
    setText('hsInterest', money.format(Math.max(0, final - s0 - D * T)));

    var lastYear = Math.min(30, Math.max(years, earliest > 0 ? Math.ceil(earliest / 12) : years));
    var html = [];
    for (var y = 1; y <= lastYear; y++) {
      var m = y * 12, c = need(m), mine = savings(s0, dep, i, m);
      html.push('<tr><td>' + y + '</td><td>' + money.format(price(p0, g, m)) + '</td><td>' + money.format(c) + '</td><td>' +
        (y <= years ? money.format(savings(s0, D, i, m)) : '–') + '</td><td>' + money.format(mine) + '</td><td>' +
        (mine >= c - 0.005 ? 'Covered' : money.format(c - mine)) + '</td></tr>');
    }
    el('hsTable').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('hsForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
